subsection.example:
START_MARKER

test_eq(sizeof("Pike"), 4)
test_equal([[reverse(({1, 2, 3}))]], [[({3, 2, 1})]])
test_any([[
  array(int) values = ({1, 2, 3});
  return sizeof(values);
]], 3)
test_eval_error([[error("Expected failure.\n");]])

END_MARKER

test_eq(1e1, 10.0)
test_any([[
  string text = "hello";
  return upper_case(text);
]], "HELLO")

test_equal([[({1, 2}) + ({3})]], [[({1, 2, 3})]])
test_any_equal([[
  array(int) values = ({1, 2, 3});
  return reverse(values);
]], [[({3, 2, 1})]])

test_true(has_prefix("Pike", "Pi"))
test_false(has_prefix("Pike", "Py"))
test_do([[
  object file = Stdio.File();
  destruct(file);
]])

test_compile([[Stdio.File file = Stdio.File();]])
test_compile_any([[
  class Counter {
    int value;
    int increment() { return ++value; }
  }
]])

test_compile_error([[int value = "not an integer";]])
test_compile_error_any([[
  int value = "not an integer";
]])

test_compile_warning([[
  class A { int value = 6; }
  class B {
    constant value = 5;
    inherit A;
  }
]])

test_eval_error([[error("Expected failure.\n");]])
test_any([[
  mixed failure = catch { error("Expected failure.\n"); };
  return failure[0];
]], "Expected failure.\n")

test_define_program(GuideCounter, [[
  int value;
  int increment() { return ++value; }
]])
test_any([[
  object counter = GuideCounter();
  counter->increment();
  return counter->increment();
]], 2)
test_do(add_constant("GuideCounter"))

test_program([[
  int value;
  int increment() { return ++value; }
  int a() { return increment() == 1 && increment() == 2; }
]])

cond([[sizeof("Pike") == 4]], [[
  test_eq(lower_case("PIKE"), "pike")
]])
cond_resolv(Stdio, [[
  test_true(programp(Stdio.File))
]])
ifefun(sizeof, [[
  test_eq(sizeof(""), 0)
]])

section.example:
// -*- pike -*- TEST: RUN-AS-PIKE-SCRIPT

int main()
{
  int succeeded;
  int failed;

  if (equal(reverse(({1, 2, 3})), ({3, 2, 1})))
    succeeded++;
  else {
    failed++;
    werror("reverse() returned an unexpected result.\n");
  }

  Tools.Testsuite.report_result(succeeded, failed);
  return failed ? 1 : 0;
}
